#!/usr/bin/env bash
# Creates firmware/src/app/secrets.h from the template and fills in the MQTT
# credentials generated by gateway/setup_pi.sh. Wi-Fi SSID/password stay
# CHANGE_ME – edit them by hand. Existing secrets.h is never overwritten.
#
#   scp buddyband-gw:buddyband-credentials.env ~/.config/buddyband/credentials.env
#   tools/make_secrets.sh
set -euo pipefail
cd "$(dirname "$0")/.."
CRED="${1:-$HOME/.config/buddyband/credentials.env}"
OUT=firmware/src/app/secrets.h
[[ -f "$OUT" ]] && { echo "$OUT exists – not touched"; exit 0; }
[[ -f "$CRED" ]] || { echo "missing $CRED (copy it from the Pi first)"; exit 1; }
# shellcheck disable=SC1090
source "$CRED"
sed "s|#define MQTT_PASS   \"CHANGE_ME\"|#define MQTT_PASS   \"${BB_TEACHER_PW}\"|" \
  firmware/src/app/secrets.h.example > "$OUT"
chmod 600 "$OUT"
git check-ignore -q "$OUT" && echo "created $OUT (git-ignored). Now set WIFI_SSID and WIFI_PASS in it."
